std::map<std::string, int> word_counts;

// 1. Assignment (inserts "hello" -> 1)
word_counts["hello"] = 1;

// 2. Auto-Insertion & Modification (Standard idiom)
// If key "world" does not exist, it is default-constructed (0), then incremented (1).
word_counts["world"]++;

// 3. Access Existing Key
int count = word_counts["hello"]; // count is 1

// 4. CAUTION: Accessing a non-existent key causes insertion
// "unknown" is inserted with default value (0).
int lookup = word_counts["unknown"];

// 5. Check size after auto-insertion
// size() will be 3: "hello", "world", "unknown"
size_t map_size = word_counts.size();
